{
  "name": "timer_set_alarm",
  "confidence": "medium",
  "docstring": "Arms the timer subsystem by storing pending and current timer entry pointers in a timer control block and setting the 0xC0 control bits on every timer table entry plus several extra timer entries.",
  "subsystem": "rf",
  "var_renames": {
    "v0": "pending_timer_entry",
    "v1": "current_entry_ptr",
    "result": "current_timer_entry",
    "v2": "timer_control_block",
    "v4": "timer_entry",
    "v5": "timer_entry_end",
    "v6": "extra_timer_entry_base",
    "v7": "timer_control_block",
    "v8": "extra_timer_entry"
  },
  "struct_hints": [
    {
      "offset": 3,
      "meaning": "byte control/status field; ORing 0xC0 marks the timer entry armed"
    },
    {
      "offset": 4,
      "meaning": "word field initialized from a pending alarm/time value"
    },
    {
      "offset": 2324,
      "meaning": "timer control block slot storing the current timer entry pointer"
    },
    {
      "offset": 2836,
      "meaning": "timer control block slot storing the pending timer entry pointer"
    }
  ]
}
